#include <algorithm>
#include <array>
#include <fstream>
using Rectangle = std::array<long long, 4>;
long long area(const Rectangle &r) {
    return (r[2] - r[0]) * (r[3] - r[1]);
}
long long overlap(const Rectangle &a, const Rectangle &b) {
    const long long width = std::max(0LL, std::min(a[2], b[2]) - std::max(a[0], b[0]));
    const long long height = std::max(0LL, std::min(a[3], b[3]) - std::max(a[1], b[1]));
    return width * height;
}
int main() {
    std::ifstream in("billboard.in");
    std::ofstream out("billboard.out");
    std::array<Rectangle, 3> rectangles;
    for (auto &rectangle : rectangles)
        for (auto &coordinate : rectangle) in >> coordinate;
    out << area(rectangles[0]) + area(rectangles[1])
        - overlap(rectangles[0], rectangles[2]) - overlap(rectangles[1], rectangles[2]) << '\n';
}
