#include <fstream>
#include <vector>
int main() {
    std::ifstream in("shuffle.in");
    std::ofstream out("shuffle.out");
    int n;
    in >> n;
    std::vector<int> destination(n), current(n);
    for (int &value : destination) in >> value;
    for (int &id : current) in >> id;
    for (int round = 0; round < 3; ++round) {
        std::vector<int> previous(n);
        for (int i = 0; i < n; ++i) previous[i] = current[destination[i] - 1];
        current = previous;
    }
    for (int id : current) out << id << '\n';
}
