#include <algorithm>
#include <array>
#include <fstream>
#include <string>
#include <vector>
struct Record {
    int day;
    std::string cow;
    int change;
};
int main() {
    std::ifstream in("measurement.in");
    std::ofstream out("measurement.out");
    int n;
    in >> n;
    std::vector<Record> records(n);
    for (auto &record : records) in >> record.day >> record.cow >> record.change;
    std::sort(records.begin(), records.end(), [](const Record &a, const Record &b) {
        return a.day < b.day;
    });
    const std::array<std::string, 3> names{"Bessie", "Elsie", "Mildred"};
    std::array<int, 3> milk{7, 7, 7};
    int display = 7, answer = 0;
    for (const auto &record : records) {
        for (int i = 0; i < 3; ++i)
            if (names[i] == record.cow) milk[i] += record.change;
        const int best = *std::max_element(milk.begin(), milk.end());
        int updated = 0;
        for (int i = 0; i < 3; ++i)
            if (milk[i] == best) updated |= 1 << i;
        if (updated != display) ++answer;
        display = updated;
    }
    out << answer << '\n';
}
